-- 데이터베이스 세트 371. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_sql_schema_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 371, 'SQL 테이블과 제약 손연습: CREATE TABLE, NOT NULL·DEFAULT·AUTO_INCREMENT·FOREIGN KEY, ALTER TABLE, DROP·TRUNCATE', '작은 가게(shop) 데이터베이스에서 테이블을 직접 만들고 바꿔 봅니다. 기본 키와 NOT NULL 로 테이블을 만들고 DESCRIBE 로 구조를 보고, 제약을 어기는 입력이 어떤 오류로 막히는지 확인하고, 기본값 있는 컬럼을 추가하고, AUTO_INCREMENT 와 FOREIGN KEY 를 써 보고, 컬럼을 원하는 자리에 추가하거나 지우고, 테이블을 DROP 하거나 TRUNCATE 로 비웁니다. 채점은 information_schema 와 테이블 상태를 직접 조회해 비교합니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 371);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 1, '테이블 만들기 (CREATE TABLE)', '**배경** — 테이블은 **컬럼(이름과 자료형)** 을 정해 만드는 표입니다. 컬럼마다 `NOT NULL`(빈 값 금지), `PRIMARY KEY`(행을 하나로 구분하는 값, 중복·빈 값 불가) 같은 **제약** 을 붙일 수 있습니다. 이 세트의 문제는 데이터베이스 `shop`(`mariadb shop -e ''쿼리''` 로 접속해 실행)을 씁니다. 처음에는 `customers`(`id`, `name`, `city`, 고객 3명), 비어 있는 `tmp_old`, 행이 3개 든 `logs`(`id`, `msg`)가 있고, 문제마다 처음 상태에서 다시 시작합니다.

**문제** — 책 정보를 담는 테이블 **`books`** 를 만드세요. 컬럼은 이 순서로: `id`(정수, **기본 키**), `title`(문자 최대 50자, **빈 값 불가**), `price`(정수).', '`CREATE TABLE 테이블 (컬럼 자료형 제약, ...);` 입니다. 문자열 자료형은 `VARCHAR(50)` 처럼 길이를 줍니다.', 'mariadb shop -e ''CREATE TABLE books (id INT PRIMARY KEY, title VARCHAR(50) NOT NULL, price INT);''
mariadb shop -e ''DESCRIBE books;''

# CREATE TABLE 에 컬럼과 제약을 괄호 안에 나열한다. DESCRIBE 로 구조를 확인한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books''\\")\\" = \\"id,title,price\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT column_key FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books'' AND column_name = ''id''\\")\\" = \\"PRI\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT is_nullable FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books'' AND column_name = ''title''\\")\\" = \\"NO\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컬럼이 id, title, price 순서다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books''\\")\\" = \\"id,title,price\\" ]"]}, {"label": "id 가 기본 키다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT column_key FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books'' AND column_name = ''id''\\")\\" = \\"PRI\\" ]"]}, {"label": "title 은 빈 값이 안 된다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT is_nullable FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''books'' AND column_name = ''title''\\")\\" = \\"NO\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 2, '테이블 구조 보기 (DESCRIBE)', '`customers` 테이블의 **구조(컬럼, 자료형, 키 등)** 를 조회해 출력을 **`/tmp/q2.txt`** 에 저장하세요.', '`DESCRIBE 테이블;` (줄여서 `DESC 테이블;`)은 컬럼 이름, 자료형, NULL 허용 여부, 키, 기본값을 보여 줍니다.', 'mariadb shop -e ''DESCRIBE customers;'' > /tmp/q2.txt
cat /tmp/q2.txt

# DESCRIBE 테이블 로 구조를 본다. Key 칸의 PRI 가 기본 키다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e ''DESCRIBE customers'')\\" ] ) && ( grep -q PRI /tmp/q2.txt && grep -qw name /tmp/q2.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 지금의 DESCRIBE 출력과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e ''DESCRIBE customers'')\\" ]"]}, {"label": "PRI 와 name 이 보인다", "cmd": ["sh", "-c", "grep -q PRI /tmp/q2.txt && grep -qw name /tmp/q2.txt"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 3, 'NOT NULL 제약이 막는 것 확인하기', '`customers` 의 `name` 은 `NOT NULL` 입니다. 이름을 **`NULL`** 로 하는 새 고객 (id 4, name `NULL`, city `Daegu`)을 넣어 보고, **나온 오류 메시지** 를 **`/tmp/q3.txt`** 에 저장하세요(`2>`). 고객은 3명 그대로여야 합니다.', '제약을 어기는 `INSERT` 는 오류가 나고 행이 들어가지 않습니다. 오류는 표준 에러 출력이라 `2> 파일` 로 저장합니다.', 'mariadb shop -e "INSERT INTO customers VALUES (4, NULL, ''Daegu'');" 2> /tmp/q3.txt
cat /tmp/q3.txt

# NOT NULL 컬럼에 NULL 을 넣으면 cannot be null 오류가 나고 행은 들어가지 않는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( grep -q \\"cannot be null\\" /tmp/q3.txt ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM customers\\")\\" = \\"3\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q3.txt 에 cannot be null 오류가 있다", "cmd": ["sh", "-c", "grep -q \\"cannot be null\\" /tmp/q3.txt"]}, {"label": "고객은 3명 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM customers\\")\\" = \\"3\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 4, '컬럼 추가와 기본값 (ALTER TABLE ADD COLUMN, DEFAULT)', '`customers` 에 **`status`** 컬럼(문자 최대 10자, **빈 값 불가**, 기본값 `active`)을 **추가** 하세요. 이미 있는 3명도 `active` 가 되어야 합니다.', '`ALTER TABLE 테이블 ADD COLUMN 컬럼 자료형 NOT NULL DEFAULT 값;` 입니다. 기본값을 주면 기존 행에도 그 값이 채워집니다.', 'mariadb shop -e "ALTER TABLE customers ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT ''active'';"
mariadb shop -e ''SELECT * FROM customers;''

# ADD COLUMN 에 NOT NULL DEFAULT 값을 주면 기존 행에도 기본값이 들어간다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT column_name FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers'' AND column_name = ''status''\\")\\" = \\"status\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT is_nullable FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers'' AND column_name = ''status''\\")\\" = \\"NO\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(status ORDER BY id) FROM customers\\")\\" = \\"active,active,active\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "status 컬럼이 생겼다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT column_name FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers'' AND column_name = ''status''\\")\\" = \\"status\\" ]"]}, {"label": "status 는 빈 값이 안 된다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT is_nullable FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers'' AND column_name = ''status''\\")\\" = \\"NO\\" ]"]}, {"label": "기존 3명이 모두 active 다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(status ORDER BY id) FROM customers\\")\\" = \\"active,active,active\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 5, '번호 자동으로 매기기 (AUTO_INCREMENT)', '**`notes`** 테이블을 만드세요: `id`(정수, **기본 키**, **자동으로 번호 매김**), `body`(문자 최대 100자). 그런 다음 `id` 를 **지정하지 않고** `body` 가 `a`, `b` 인 두 행을 넣으세요.', '컬럼에 `AUTO_INCREMENT` 를 주면 값을 안 넣어도 1부터 차례로 채워집니다. 일부 컬럼만 넣으려면 `INSERT INTO 테이블 (컬럼) VALUES (...)` 로 컬럼을 적습니다.', 'mariadb shop -e ''CREATE TABLE notes (id INT AUTO_INCREMENT PRIMARY KEY, body VARCHAR(100));''
mariadb shop -e "INSERT INTO notes (body) VALUES (''a''), (''b'');"
mariadb shop -e ''SELECT * FROM notes;''

# AUTO_INCREMENT 컬럼은 값을 안 넣으면 1, 2, ... 로 자동 채워진다. 넣을 컬럼만 (body) 로 적는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT extra FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''notes'' AND column_name = ''id''\\")\\" = \\"auto_increment\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM notes\\")\\" = \\"1,2\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(body ORDER BY id) FROM notes\\")\\" = \\"a,b\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "id 가 자동 번호 컬럼이다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT extra FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''notes'' AND column_name = ''id''\\")\\" = \\"auto_increment\\" ]"]}, {"label": "id 가 1, 2 로 채워졌다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM notes\\")\\" = \\"1,2\\" ]"]}, {"label": "body 가 a, b 다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(body ORDER BY id) FROM notes\\")\\" = \\"a,b\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 6, '다른 테이블을 가리키는 제약 (FOREIGN KEY)', '**배경** — **외래 키** 는 "이 컬럼의 값은 다른 테이블에 실제로 있는 값이어야 한다"는 제약입니다.

**문제** — **`pets`** 테이블을 만드세요: `id`(정수, 기본 키), `owner_id`(정수), `name`(문자 최대 30자), 그리고 `owner_id` 가 `customers` 의 `id` 를 가리키는 **외래 키**. 그런 다음 `customers` 에 **없는** 주인 번호 99 로 반려동물 (1, 99, `rex`)을 넣어 보고 **나온 오류** 를 **`/tmp/q6.txt`** 에 저장하세요(`2>`).', '`FOREIGN KEY (컬럼) REFERENCES 다른테이블(컬럼)` 을 `CREATE TABLE` 괄호 안에 적습니다. 없는 값을 넣으면 `foreign key constraint fails` 오류가 납니다.', 'mariadb shop -e ''CREATE TABLE pets (id INT PRIMARY KEY, owner_id INT, name VARCHAR(30), FOREIGN KEY (owner_id) REFERENCES customers (id));''
mariadb shop -e "INSERT INTO pets VALUES (1, 99, ''rex'');" 2> /tmp/q6.txt
cat /tmp/q6.txt

# FOREIGN KEY ... REFERENCES 로 없는 값을 막는다. 위반하면 foreign key constraint fails 오류가 난다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema = ''shop'' AND table_name = ''pets'' AND referenced_table_name = ''customers''\\")\\" = \\"1\\" ] ) && ( grep -qi \\"foreign key constraint fails\\" /tmp/q6.txt ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM pets\\")\\" = \\"0\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "pets 의 owner_id 가 customers 를 가리킨다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema = ''shop'' AND table_name = ''pets'' AND referenced_table_name = ''customers''\\")\\" = \\"1\\" ]"]}, {"label": "q6.txt 에 foreign key constraint fails 오류가 있다", "cmd": ["sh", "-c", "grep -qi \\"foreign key constraint fails\\" /tmp/q6.txt"]}, {"label": "pets 에는 행이 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM pets\\")\\" = \\"0\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 7, '컬럼을 원하는 자리에 추가하기 (AFTER)', '`customers` 에 **`email`** 컬럼(문자 최대 60자)을 **`name` 바로 뒤** 에 추가하세요. 컬럼 순서는 `id, name, email, city` 가 되어야 합니다.', '`ADD COLUMN ... AFTER 기준컬럼` 으로 위치를 정합니다. 위치를 안 주면 맨 뒤에 붙습니다.', 'mariadb shop -e ''ALTER TABLE customers ADD COLUMN email VARCHAR(60) AFTER name;''
mariadb shop -e ''DESCRIBE customers;''

# AFTER 컬럼 으로 추가 위치를 지정한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers''\\")\\" = \\"id,name,email,city\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컬럼 순서가 id, name, email, city 다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers''\\")\\" = \\"id,name,email,city\\" ]"]}, {"label": "기존 이름은 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 8, '컬럼 지우기 (DROP COLUMN)', '`customers` 에서 **`city`** 컬럼을 **삭제** 하세요. 나머지 컬럼과 데이터는 그대로여야 합니다.', '`ALTER TABLE 테이블 DROP COLUMN 컬럼;` 입니다. 컬럼을 지우면 그 컬럼의 값도 함께 사라집니다.', 'mariadb shop -e ''ALTER TABLE customers DROP COLUMN city;''
mariadb shop -e ''DESCRIBE customers;''

# DROP COLUMN 은 컬럼과 그 안의 값을 함께 지운다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers''\\")\\" = \\"id,name\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컬럼이 id, name 만 남았다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = ''shop'' AND table_name = ''customers''\\")\\" = \\"id,name\\" ]"]}, {"label": "고객 이름은 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 9, '테이블 지우기와 비우기 (DROP, TRUNCATE)', '쓰지 않는 테이블 **`tmp_old` 를 삭제**(테이블 자체가 없어지게)하고, `logs` 는 **행만 모두 비우세요**(테이블 구조는 남김).', '`DROP TABLE` 은 테이블 자체를, `TRUNCATE TABLE` 은 구조는 두고 모든 행만 지웁니다.', 'mariadb shop -e ''DROP TABLE tmp_old;''
mariadb shop -e ''TRUNCATE TABLE logs;''
mariadb shop -e ''SHOW TABLES;''

# DROP TABLE 은 테이블을 없애고, TRUNCATE TABLE 은 행만 모두 지운다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\");\\nCREATE TABLE tmp_old (id INT);\\nCREATE TABLE logs (id INT, msg VARCHAR(50));\\nINSERT INTO logs VALUES (1,\\"start\\"),(2,\\"work\\"),(3,\\"end\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = ''shop'' AND table_name = ''tmp_old''\\")\\" = \\"0\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = ''shop'' AND table_name = ''logs''\\")\\" = \\"1\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM logs\\")\\" = \\"0\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "tmp_old 가 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = ''shop'' AND table_name = ''tmp_old''\\")\\" = \\"0\\" ]"]}, {"label": "logs 테이블은 남아 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = ''shop'' AND table_name = ''logs''\\")\\" = \\"1\\" ]"]}, {"label": "logs 의 행이 0개다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM logs\\")\\" = \\"0\\" ]"]}]', '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 9);

