SELECT 371, 10, '기본 키와 UNIQUE 의 차이는?', '한 테이블에서 **`PRIMARY KEY`** 와 **`UNIQUE`** 제약을 비교한 설명으로 맞는 것은 무엇일까요?', '한 테이블에 몇 개까지 둘 수 있는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["기본 키는 여러 개 둘 수 있고, UNIQUE 는 테이블에 하나만 둘 수 있다", "기본 키는 테이블에 하나만 둘 수 있고, UNIQUE 는 여러 컬럼에 각각 둘 수 있다", "둘 다 중복을 막지만 기본 키는 컬럼이 하나일 때만 쓸 수 있다", "기본 키는 중복을 허용하고, UNIQUE 만 중복을 막는다"]', 1, '`PRIMARY KEY` 는 행을 하나로 구분하는 값이라 테이블에 **하나만** 있고 빈 값(`NULL`)을 허용하지 않습니다. `UNIQUE` 는 중복만 막으며 여러 컬럼에 각각 둘 수 있습니다. 둘 다 중복을 막고, 기본 키는 여러 컬럼을 묶어서도 만들 수 있습니다.', NULL, NULL, NULL, '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 11, '외래 키 만들기', '`owner_id` 가 `customers` 의 `id` 를 **가리키도록** 하는 외래 키 문장의 빈칸을 채우세요.', '"참조하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["REFERENCES", "POINTS", "LINKS", "BINDS"]', NULL, '`FOREIGN KEY (컬럼) REFERENCES 다른테이블 (컬럼)` 으로 다른 테이블의 컬럼을 참조합니다. `POINTS`·`LINKS`·`BINDS` 는 이 자리에 쓰는 키워드가 아닙니다.', '[0]', 'FOREIGN KEY (owner_id) {0} customers (id)', NULL, '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 371, 12, '테이블 만들어 쓰고 바꾸는 흐름', '테이블을 만들고 쓰다가 구조를 바꾸고 정리하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 넣기 → 바꾸기 → 정리 순서예요.', NULL, NULL, '[]', 'order', '["`CREATE TABLE` 로 테이블과 제약을 만든다", "`INSERT` 로 행을 넣는다", "`ALTER TABLE` 로 컬럼을 추가하거나 바꾼다", "쓰지 않으면 `DROP TABLE` 로 지운다"]', NULL, '테이블을 만들고 데이터를 넣어 쓰다가, 필요하면 `ALTER TABLE` 로 구조를 바꾸고, 더 쓰지 않으면 `DROP TABLE` 로 지웁니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}, {"title": "MariaDB ALTER TABLE", "url": "https://mariadb.com/kb/en/alter-table/"}, {"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB AUTO_INCREMENT", "url": "https://mariadb.com/kb/en/auto_increment/"}, {"title": "MariaDB DESCRIBE", "url": "https://mariadb.com/kb/en/describe/"}, {"title": "MariaDB DROP TABLE", "url": "https://mariadb.com/kb/en/drop-table/"}, {"title": "MariaDB TRUNCATE TABLE", "url": "https://mariadb.com/kb/en/truncate-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 371 AND order_index = 12);

